                (p[0] / max(1, a - 1)) ** 2 + (1 - p[1] / max(1, b - 1)) ** 2,
                (1 - p[0] / max(1, a - 1)) ** 2 + (p[1] / max(1, b - 1)) ** 2,
                (1 - p[0] / max(1, a - 1)) ** 2 + (1 - p[1] / max(1, b - 1)) ** 2,
            )
        )

    ext_points = [p for color in anchors for p in outside[color]]
    if len(anchors) >= 2 and ext_points:
        er0 = min(p[0] for p in ext_points)
        er1 = max(p[0] for p in ext_points)
        ec0 = min(p[1] for p in ext_points)
