        transforms = ("id", "r90", "r180", "r270", "fh", "fv", "tr", "anti")

        def mapped(name, y, x):
            if name == "id":   return y, x
            if name == "r90":  return x, 1 - y
            if name == "r180": return 1 - y, 1 - x
            if name == "r270": return 1 - x, y
            if name == "fh":   return y, 1 - x
            if name == "fv":   return 1 - y, x
            if name == "tr":   return x, y
